{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "PET in cynomolgus monkey showed rapid brain uptake and striatal accumulation of 11C-SCH23390, a close structural analogue of the query, demonstrating that the chlorohydroxy-N-methylbenzazepine core readily crosses the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "In healthy humans, 11C-SCH23390 showed rapid transfer into the brain with 1.2% of injected radioactivity present at 4.5 min, providing direct human evidence of meaningful CNS access for the query's core scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "The 4-iodophenyl analogue showed good rat brain uptake (2.27% dose/whole brain at 2 min after IV injection), indicating that para-halogen substitution on the pendant aryl ring is compatible with BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "The 3-iodophenyl analogue had good initial brain uptake (1.59% dose/organ at 2 min) in rats, supporting that meta-halogenated aryl substituents retain CNS penetration in this benzazepine series.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "123I-SCH23982 showed a brain-to-blood ratio of about 1.2 at 10 min in rats, indicating active brain uptake and reinforcing the CNS-penetrant behavior of the benzazepine scaffold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a close analogue of SCH23390 and related halogenated 3-benzazepines that show rapid, meaningful brain uptake across species, including humans. The bromodihydrobenzofuranyl substituent adds lipophilic aromatic character and is unlikely to abolish the CNS penetration established for the core scaffold.",
  "evidence_gaps": [
    "No direct experimental measurement exists for the exact query molecule.",
    "Quantitative unbound brain or CSF exposure data are not available for the query.",
    "Potential efflux-transporter liability of the bromodihydrobenzofuranyl group was not directly assessed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

